class Token:
    def __init__(self, type_, value):
        self.type_ = type_
        self.value = value

def tokenize(expr: str):
    tokens = []
    current_number = ''

    for char in expr:
        if char.isdigit() or char == '.':
            current_number += char
        else:
            if current_number:
                tokens.append(Token('NUMBER', float(current_number)))
                current_number = ''
            if char in "+-*/()":
                tokens.append(Token(char, char))
    if current_number:
        tokens.append(Token('NUMBER', float(current_number)))

    return tokens

def parse(tokens):
    def parse_expression(index):
        left_value, index = parse_term(index)
        while index < len(tokens) and tokens[index].type_ in ('+', '-'):
            op = tokens[index].value
            index += 1
            right_value, index = parse_term(index)
            left_value = left_value + right_value if op == '+' else left_value - right_value
        return left_value, index

    def parse_term(index):
        left_value, index = parse_factor(index)
        while index < len(tokens) and tokens[index].type_ in ('*', '/'):
            op = tokens[index].value
            index += 1
            right_value, index = parse_factor(index)
            left_value = left_value * right_value if op == '*' else left_value / right_value
        return left_value, index

    def parse_factor(index):
        if tokens[index].type_ == 'NUMBER':
            number = tokens[index].value
            index += 1
            return number, index
        elif tokens[index].type_ == '(':
            index += 1
            value, index = parse_expression(index)
            index += 1  # consume ')'
            return value, index
        raise SyntaxError("Unexpected token")

    result, _ = parse_expression(0)
    return result

